//! The persisted format: the version number, the reader's caps, and the
//! read-any-version / write-current pair behind `project.json` in a
//! `.framejob` package (spec §5.6).
//!
//! The rule this module exists to enforce: **the reader accepts every prior
//! version, and the writer enforces the reader's caps**, so every file this
//! build produces can be read back by this build. Any change to the
//! persisted schema bumps [`RC_FORMAT_VERSION`] here AND the `#define` in
//! `core/include/framejob_core.h`, and adds a migration step in [`read`].

use serde_json::{json, Value};

use crate::model::{Canvas, Project};

/// Bumped by any change to the persisted project schema. Mirrored by
/// `RC_FORMAT_VERSION` in the C header.
/// What each version added is [`crate::format_history`].
pub const RC_FORMAT_VERSION: u32 = 43;

/// The number the grading branch's builds wrote (spec §11 GR-9); read as version 15.
pub const GRADING_BRANCH_VERSION: u32 = 1015;

/// Reader caps, mirrored by the `RC_MAX_*` defines in the C header. They
/// exist so a corrupt or generated file cannot make the app allocate
/// without bound, and they are generous: 4096 clips is far past what the
/// timeline UI stays usable at.
pub const MAX_CLIPS: usize = 4096;
pub const MAX_TRACKS: usize = 64;
pub const MAX_MARKERS: usize = 1024;
pub const MAX_MEDIA: usize = 1024;

/// The largest `.cube` file `cube.rs` reads (spec §11 GR-8): 32 MiB, which
/// holds a 65³ table four times over at the precision tools write, and keeps
/// a stray file named `.cube` from being read whole. Mirrored by
/// `RC_CUBE_MAX_BYTES` in the C header; the app reads at most one byte more,
/// so a larger file is refused by the core's own sentence.
pub const RC_CUBE_MAX_BYTES: usize = 33_554_432;

/// How many levels of nest may sit inside one another. A cap on the WALK,
/// not on taste: every evaluation of a nested layer recurses once per
/// level, and eight levels is already past anything an editor does on
/// purpose. `Project::validate` refuses a deeper file, and it refuses a
/// nest that reaches itself at any depth, so no walk downstream needs a
/// visited set of its own.
pub const MAX_NEST_DEPTH: u32 = 8;

/// The caps check both sides share: [`Project::validate`] runs it on read,
/// [`write`] runs it before serializing. One implementation, so the writer
/// can never produce a file the reader rejects.
///
/// Nested tracks and clips count toward the same two caps as the
/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    if p.markers.len() > MAX_MARKERS {
        return Err(format!(
            "too many markers: {} (max {})",
            p.markers.len(),
            MAX_MARKERS
        ));
    }
    if p.media.len() > MAX_MEDIA {
        return Err(format!(
            "too many media: {} (max {})",
            p.media.len(),
            MAX_MEDIA
        ));

                    return Err(format!(
                        "media {} is shorter than a frame ({} ticks; a frame is {} ticks)",
                        media.id,
                        media.duration,
                        self.snapped_up(1)
                    ));
                }
                Ok(duration)
            }
        }
    }

    // ---- adding clips ----------------------------------------------------

    /// Places the whole of `media` as one clip at `at` on `track`, source
    /// in 0, with Fit scale when the canvas asks for it and the source
    /// exceeds it (spec §6).
    ///
    /// `video` is `null` for an audio-only file and `audio` is `null` for a
    /// file with no audio track, which is how the inspector knows which
    /// tabs to enable. Refuses when the placement breaks the overlap rule;
    /// `Err` for an unknown track or media, or a media with no usable
    /// duration.
    pub fn add_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        self.require_track(track)?;
        let found = self.require_media(media)?.clone();
        // A drag can start left of zero; the timeline has no negative time.
        let at = self.snapped(at).max(0);

        let duration = self.whole_media_length(&found)?;
        let source = match found.kind {
            MediaKind::Image => Source::Image { media },
            MediaKind::Video | MediaKind::Audio => Source::Media {
                media,
                r#in: 0,
                reversed: false,
            },
            MediaKind::Lut => return Err(crate::lut::lut_not_placeable(media)),
        };

        let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
        let video = has_pixels.then(|| VideoProps {
            scale: self.fit_scale(f64::from(found.width), f64::from(found.height)),
            ..VideoProps::default()
        });
        let audio = found.has_audio.then(AudioProps::default);

        let mut next = self.clone();
        let clip = Clip {
            video,
            audio,
            ..Clip::placed(next.allocate_id(), track, at, duration, source)
        };
        self.commit_additions(next, vec![clip])
    }

    // ---- moving -----------------------------------------------------------

    /// Shifts `clips` by `delta` ticks and, when `track` is given, moves
    /// them to that track keeping their relative track offsets (spec §6).
    ///
    /// The EARLIEST clip clamps at 0 and the rest keep their offsets, so a
    /// drag past the start of the timeline compresses nothing. The
    /// destination is computed as an index delta from the first clip of the
    /// selection (by track order, then start), which is what makes a
    /// two-track selection land two tracks apart.
    ///
    /// Refuses when a clip would land outside the track list or the overlap
    /// rule fails on any affected track. A clip that gains a predecessor
    /// overlap and has no transition gets a cross dissolve.
    ///
    /// **A linked partner follows in TIME, not in track** (spec §11 AU-91):
    /// every clip of the closure moves by the one delta, the clamp at 0 is
    /// taken over the closure so a J-cut's lead is kept, and the track delta
    /// is anchored on and applied to the CALLER's clips only — so a sound
    /// half dragged to a track of its own goes alone and its picture stays.
    pub fn move_clips(
        &self,
        clips: &[u32],
        delta: Ticks,
        track: Option<u32>,
    ) -> Result<Outcome, String> {
        let selection = self.selected_clips(clips)?;
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let closure = self.selected_clips(&self.with_links(clips)?)?;

        // Snapping the delta keeps a dragged clip on the grid: every start
        // is already on it, so a snapped delta lands on it too.
        let mut delta = self.snapped(delta);
        let earliest = closure.iter().map(|c| c.start).min().unwrap_or(0);
        if delta < -earliest {
            delta = -earliest;
        }

        let index_delta = match track {
            None => 0i64,
            Some(destination) => {
                let destination_index = self.require_track_index(destination)? as i64;
                // The anchor is the FIRST clip of the selection in the
                // order the timeline draws — back-most track, then earliest
                // — and the whole selection moves by its offset, which is
                // what keeps a two-track selection two tracks apart.
                let mut keyed: Vec<(usize, Ticks, u32)> = Vec::new();
                for clip in &selection {
                    keyed.push((self.require_track_index(clip.track)?, clip.start, clip.id));
                }
                let anchor = keyed.iter().min().map(|k| k.0).unwrap_or(0) as i64;
                destination_index - anchor
            }
        };

        let mut candidates: Vec<Clip> = Vec::new();
        for clip in &closure {
            let mut moved = (*clip).clone();
            moved.start = moved.start.saturating_add(delta).max(0);
            let named = selection.iter().any(|c| c.id == clip.id);
            if index_delta != 0 && named {
                let from = self.require_track_index(clip.track)? as i64;
                let to = from.saturating_add(index_delta);
                // A selection dragged off either end of the track list is a
                // refusal and not a clamp — clamping would silently stack
                // two clips on one track — and it says so in `move_track`'s
                // own words for the same mistake.
                let Some(destination) = usize::try_from(to)
                    .ok()
                    .and_then(|index| self.tracks.get(index))
                else {
                    return Ok(Outcome::Refused(format!(
                        "clip {} would land on track index {to}, which is out of range (0..{})",
                        clip.id,
                        self.tracks.len()
                    )));
                };
                moved.track = destination.id;
            }
            candidates.push(moved);
        }

        self.commit_replacements(candidates)
    }

    /// The named clips, deduplicated, in the order given. `Err` on an
    /// unknown id — every multi-clip op names its clips explicitly, so a
    /// stale id is a caller bug, not a refusal.
    pub(crate) fn selected_clips(&self, clips: &[u32]) -> Result<Vec<&Clip>, String> {
        let mut out: Vec<&Clip> = Vec::new();
        for id in clips {
            let clip = self.require_clip(*id)?;
            if !out.iter().any(|c| c.id == clip.id) {
                out.push(clip);
            }
        }
        Ok(out)
    }

    // ---- splitting, deleting, duplicating --------------------------------

    /// Cuts each named clip at project time `at` (spec §6). A clip `at` is
    /// not strictly inside is skipped; when nothing can be cut the whole op
    /// is an identity. `Err` only for an unknown clip id.
    ///
    /// A linked partner is cut too, and the halves are paired (spec §11
    /// AU-92, `edit_link.rs`'s `pair_split_halves`).
    pub fn split_clips(&self, clips: &[u32], at: Ticks) -> Result<Outcome, String> {
        let at = self.snapped(at);
        let ids = self.with_links(clips)?;
        let mut next = self.clone();
        let mut halves: Vec<(u32, u32)> = Vec::new();
        for id in ids {
            // `split_clip` allocates the second half's id first.
            let second = next.next_id;
            if split_clip(&mut next, id, at) {
                halves.push((id, second));
            }
        }
        if halves.is_empty() {
            return Ok(Outcome::Identity);
        }
        pair_split_halves(&mut next, &halves);
        self.finish(next)
    }

    /// Cuts every clip on an UNLOCKED track that `at` falls strictly inside
    /// — ⌘K with no selection (spec §6, §9).
    ///
    /// The SELECTION is all this op computes; the cutting is
    /// [`Project::split_clips`]'s, called rather than copied, so the two
    /// spellings of ⌘K cannot answer differently. An empty selection is its
    /// identity, which is the same answer a list of clips none of which
//! Insert and overwrite — spec §6 rows `insert_clip` and `overwrite_clip`.
//!
//! The two ways to bring new material into a cut that is already timed.
//! An **insert** makes room for it: the track is cut under the drop point
//! and everything from there on moves later by the new clip's length, so
//! nothing is lost and every following clip keeps its relative timing. An
//! **overwrite** takes room from what is there: the span the new clip needs
//! is cleared on that track alone and nothing moves at all, so the cut's
//! total length and every other track are untouched — but for a cut clip's
//! linked partner, which `split_clips` cuts at the same bound (spec §11
//! AU-92).
//!
//! Both are compositions of ops that already exist — `split_clips`,
//! `insert_time`, `add_clip` — and both are ONE op anyway, for two reasons.
//! The first is undo: a drop from the media list is one gesture and must be
//! one step, and three ops applied in a row are three. The second is that
//! the composition has a rule in it that neither half states — an insert
//! cuts only the DESTINATION track and then shifts every unlocked one, so
//! the straddling clips elsewhere ride the shift whole (spec §11's rule 3)
//! while the one under the drop is cut. Written out at each call site, that
//! rule would be restated in the timeline, the menu and the MCP handler.
//!
//! Neither op invents a length: `whole_media_length` is what `add_clip`
//! itself uses, so the room an insert opens is exactly the room the clip
//! needs.

use crate::edit_clip::clip_end;
use crate::edit_time::locked_track;
use crate::model::Project;
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Project {
    /// The insert edit: `media` lands whole at `at` on `track`, and
    /// everything at or after `at` moves later by its length (spec §6).
    ///
    /// The clip `at` falls strictly inside on THIS track is split first, so
    /// the insert lands between two clips rather than on top of one. Other
    /// tracks are not cut: `insert_time` shifts them whole, straddlers
    /// staying put, which is what keeps a music bed unbroken under an
    /// insert into the picture. The one exception is a cut clip's linked
    /// partner on an unlocked track, which `split_clips` cuts at the same
    /// `at` and pairs with it (spec §11 AU-92), so the pair stays in step
    /// through the inserted time.
    ///
    /// **A locked destination track refuses**, up front rather than by
    /// collision. `insert_time` will not shift a locked track, so the room
    /// an insert promises cannot be made there at all; leaving it to
    /// `add_clip` to notice would refuse only where the locked track
    /// happened to hold something at `at`, and quietly add a clip to a
    /// locked track everywhere else. `close_gap` refuses for the same
    /// reason.
    ///
    /// `Err` for an unknown track or media, or a media with no duration; a
    /// locked destination track refuses in [`locked_track`]'s words, and so
    /// does anything the inner `split`, `insert_time` or `add_clip` refused
    /// — this op answers in the words of whichever step declined.
    pub fn insert_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        if self.require_track(track)?.locked {
            return Ok(Outcome::Refused(locked_track(
                track,
                "an insert cannot open room on it",
            )));
        }
        let found = self.require_media(media)?.clone();
        let at = self.snapped(at).max(0);
        let length = self.whole_media_length(&found)?;

        let straddling: Vec<u32> = self
            .clips_on_track(track)
            .iter()
            .filter(|c| c.start < at && at < clip_end(c))
            .map(|c| c.id)
            .collect();
        let mut next = match self.split_clips(&straddling, at)? {
            Outcome::Applied(split) => split,
            // Nothing straddled the insertion point, which is the ordinary
            // case: carry on with the project as it is.
            Outcome::Identity => self.clone(),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        match next.insert_time(at, length)? {
            Outcome::Applied(opened) => next = opened,
            Outcome::Identity => {}
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        }
        // A composition answers in the words of whichever step declined, so
        // the overlap rule's sentence reaches the caller through here too.
        let placed = match next.add_clip(track, media, at)? {
            Outcome::Applied(placed) => placed,
            Outcome::Identity => return Ok(Outcome::Identity),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        self.finish(placed)
    }

    /// The overwrite edit: `media` lands whole at `at` on `track`, and
    /// whatever that track was playing across the span it needs is removed
    /// (spec §6). Nothing moves, and no other track is touched but for a
    /// cut clip's linked partner on an unlocked track: `split_clips` cuts it
    /// at the same bounds and pairs the pieces (spec §11 AU-92), and the
    /// partner's middle piece stays, its link settled away with the
    /// picture it was paired to.
    ///
    /// The span is cut at both bounds first, so everything that touched it
    /// afterwards lies entirely inside it and can be dropped whole; a clip
    /// that covered the whole span becomes a head and a tail with the new
    /// clip between them.
    ///
    /// The named track is cleared whether or not it is LOCKED — the caller
    /// named it, exactly as `ripple_delete` removes the clips it was given
    /// — while a lock still decides what may shift, which here is nothing.
    ///
    /// `Err` for an unknown track or media, or a media with no duration;
    /// whatever `add_clip` answered when the clip could not be placed after
    /// the span was cleared, in its own words.
    pub fn overwrite_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        self.require_track(track)?;
        let found = self.require_media(media)?.clone();
        let at = self.snapped(at).max(0);
        let length = self.whole_media_length(&found)?;
        // Both bounds are already on the frame grid, so the span is too.
        let end = at.saturating_add(length);

        let mut next = self.clone();
        for bound in [at, end] {
            let cut: Vec<u32> = next
                .clips_on_track(track)
                .iter()
                .filter(|c| c.start < bound && bound < clip_end(c))
                .map(|c| c.id)
                .collect();
            match next.split_clips(&cut, bound)? {
                Outcome::Applied(project) => next = project,
                Outcome::Identity => {}
                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
            }
        }
        let inside: Vec<u32> = next
            .clips_on_track(track)
            .iter()
            .filter(|c| c.start >= at && clip_end(c) <= end)
            .map(|c| c.id)
            .collect();
        next.clips.retain(|c| !inside.contains(&c.id));

        let placed = match next.add_clip(track, media, at)? {
            Outcome::Applied(placed) => placed,
            Outcome::Identity => return Ok(Outcome::Identity),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        self.finish(placed)
    }
}

//! Clip timing operations: trims and rate changes with source and action bounds.

use crate::edit_clip::clip_end;
use crate::edit_speed_profile::profile_factors;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::source_advanced_through;
use crate::time::Ticks;

/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
/// #41). The app reads it through `rc_speed_limits` and never retypes it.
pub(crate) const SPEED_MIN: f64 = 0.1;
pub(crate) const SPEED_MAX: f64 = 1000.0;

/// The fastest a clip's audio still plays, in both pitch modes (spec §11
/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
/// clip's audio segment out (`evaluate.rs`); the video still runs to
/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
/// export's loudness pass never finishes for a keep-pitch clip that starts
/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
/// the mixer and an audio-only export, and are not the product's ceiling.
pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;

/// Every number about speed, as `rc_speed_limits` publishes it:
/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
pub(crate) fn speed_limits() -> serde_json::Value {
    serde_json::json!({
        "min": SPEED_MIN,
        "max": SPEED_MAX,
        "audio_max": AUDIO_SPEED_MAX,
    })
}

impl Project {
    /// Moves the clip's start edge to `to`, advancing the source in point
    /// by `(to - start) × speed` so the frame under the edge does not move
    /// (spec §6).
    ///
    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
    /// D4-5) — and to leaving at least one frame of clip. Actions are
    /// deliberately left alone: clip-relative, rebasing would drop or bake
    /// whatever fell off the front, which is lossy and makes trimming back
    /// out not an identity. On a RAMPED clip the actions keep their clip
    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
    /// rate moving out, and the edge is held where the clip still fits its
    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
    /// new start can change. `text.words` are the opposite, on purpose
    /// (spec §11, W-3): a word is anchored to speech that stays where it is
    /// on the timeline, so every word is rebased by the trim's delta and a
    /// word trimmed off the front keeps its (negative) time. A graphic's
    /// `in` advances by the same delta (road map 10's G-9), with no speed
    /// and no head bound, never below 0.
    ///
    /// Without `alone`, a linked partner whose start is this clip's is
    /// trimmed to the same `to` after it, by its own clamps; with it, the
    /// clip moves alone — the J-cut (spec §11 AU-93, `carried_edge`).
    pub fn trim_start(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start,
            |project, id| project.trim_start_one(id, to),
        )
    }

    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let end = clip_end(&target);
        let latest = end.saturating_sub(self.frame());
        let mut to = self.snapped(to).min(latest).max(0);

        if let Some(earliest) = self.earliest_start_on_grid(&target) {
            to = to.max(earliest.max(0));
        }
        // A ramped clip's edge is held where the clip still fits its media
        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
        let to = self.front_edge_held(&target, to);
        // The two clamps can cross when the source has almost nothing left
        // in front: then there is no legal new start, so nothing happens.
        if to > latest || to == target.start {
            return Ok(Outcome::Identity);
        }

        let delta = to.saturating_sub(target.start);
        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, delta);
        moved.start = to;
        moved.duration = end.saturating_sub(to);
        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, delta);
        }
        self.commit_replacements(vec![moved])
    }

    /// Moves the clip's end edge to `to`, clamped to the source's remaining
    /// length (media sources) and to at least one frame of clip (spec §6).
    /// The source in point and the actions are untouched. The bound is
    /// `source_window.rs`'s `latest_end_on_grid`, measured at this clip's
    /// OWN start: the last frame at or before the end of the file, and
    /// never the one past it (spec §11, #22 and D4-2). A ramped clip's bound
    /// reads its map on past the end (S∞, spec §11 SR-18 (a)). A graphic's
    /// `length` is untouched: null follows the new end, a number stays (G-9).
    /// `alone` is `trim_start`'s: without it a linked partner ending where
    /// this clip ends follows; with it, the L-cut (spec §11 AU-93).
    pub fn trim_end(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| clip_end(partner) == clip_end(target),
            |project, id| project.trim_end_one(id, to),
        )
    }

    fn trim_end_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let earliest = target.start.saturating_add(self.frame());
        let mut to = self.snapped(to).max(earliest);
        if let Some(latest) = self.latest_end_on_grid(&target) {
            to = to.min(latest);
        }
        if to < earliest || to == clip_end(&target) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.duration = to.saturating_sub(target.start);
        self.commit_replacements(vec![moved])
    }

    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
    /// source range it shows: `speed = source_len / (to_end - start)`
    /// (spec §6). Media sources only.
    ///
    /// An IDENTITY when the new length is under a frame or the resulting rate
    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
    /// breaks the overlap rule. Actions keep their clip-relative fraction.
    ///
    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
    /// start) through `scaled_profile`, so the ramp keeps its shape and its
    /// window; an f that would take any rate the clip names past the limits
    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
    /// Refused on a linked clip (spec §11 AU-94).
    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        let to_end = self.snapped(to_end);
        let duration = to_end.saturating_sub(target.start);
        if duration < self.frame() {
            return Ok(Outcome::Identity);
        }
        if let Some((low, high)) = profile_factors(&target) {
            let factor = target.duration as f64 / duration as f64;
            if !factor.is_finite() || !(low..=high).contains(&factor) {
                return Ok(Outcome::Identity);
            }
            let moved = self.scaled_profile(&target, factor, duration);
            return self.commit_rate(&target, moved);
        }
        let rate = self.content_length_in_source(&target) as f64 / duration as f64;
        if !rate.is_finite() || !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Identity);
    ) -> [Ticks] {
        var all = core
        all.append(playhead)
        if let range = range {
            all.append(range.start)
            all.append(range.end)
        }
        return Array(Set(all)).sorted()
    }
}

// MARK: - Clip drag

/// Moving clips in time and across tracks (spec §4.4, §6 `move_clip`).
///
/// The preview *is* the edit: every tick calls `ProjectDocument.updateLiveEdit`
/// with `ops`, which re-applies to the handle the gesture started from, so
/// the bars the user drags are the core's own answer and a tick the core
/// refuses simply leaves the last good frame on screen (spec §7.6).
///
/// ⌥ duplicates. `duplicate` mints its copies inside the core, so the ids to
/// move are learned once at mouse-down by applying `duplicate` to the
/// current handle PURELY (`TimelineView.onProbe`) — a question, not an edit.
struct ClipDragSession {
    /// Every dragged clip, the anchor first is not required — `anchor` names
    /// it explicitly.
    let clips: [UInt32]
    let anchor: UInt32
    let anchorStart: Ticks
    let anchorRow: Int
    /// Time under the pointer at mouse-down, so the bar does not jump to
    /// centre itself on the cursor.
    let grabTime: Ticks
    /// Earliest start in the dragged set: the group's own origin, which is
    /// what snapping tests against a candidate.
    let spanStart: Ticks
    let trackCount: Int
    let duplicating: Bool
    /// Ids `duplicate` will mint, in the same order as `clips` sorted by
    /// start; empty when the probe failed and the drag falls back to a move.
    let copies: [UInt32]
    /// How far `duplicate` pushed the copies past the originals, so the move
    /// that follows lands them under the pointer and not past the span.
    let copyShift: Ticks
    /// Ids `add_track` will mint for a drop above the top lane / below the
    /// bottom one, probed with the same op PREFIX the drop will use so the
    /// core mints them in the same order. nil disables that end.
    let newTrackTop: UInt32?
    let newTrackBottom: UInt32?

    var delta: Ticks = 0
    var row: Int
    /// Non-nil while the drag is locked to a snap candidate.
    var guide: Ticks?
    /// False until the pointer actually leaves the press point — a click
    /// that merely selects must not register an undo step.
    var didMove = false

    /// True when the drop is past either end of the stack, which spec §4.4
    /// turns into a new track rather than a refusal.
    var needsNewTrack: Bool { row < 0 || row >= trackCount }

    /// Where `add_track` inserts it: model index `trackCount` (the front) for
    /// a drop above the top lane, 0 (the back) for one below the bottom.
    var newTrackIndex: Int { row < 0 ? trackCount : 0 }

    /// The anchor's proposed start — what the refusal check compares against
    /// once the core has had its say.
    var proposedStart: Ticks { anchorStart + delta }

    /// The ops for the current drag state, as ONE undo step.
    ///
    /// Order matters and is the order the probes assumed: `duplicate` first
    /// (so its copies take the low ids), then `add_track`, then the move.
    /// `destination` is the id of an EXISTING track to land on, or nil to
    /// leave every clip where it is vertically.
    func ops(destination: UInt32?) -> [ReelOp] {
        var ops: [ReelOp] = []
        let moved = duplicating && !copies.isEmpty ? copies : clips
        let shift = duplicating && !copies.isEmpty ? delta - copyShift : delta
        if duplicating, !copies.isEmpty {
            ops.append(.duplicate(clips: clips))
        }
        var target = destination
        if needsNewTrack, let created = row < 0 ? newTrackTop : newTrackBottom {
            ops.append(.addTrack(index: newTrackIndex))
            target = created
        }
        ops.append(.moveClip(clips: moved, delta: shift, track: target))
        return ops
    }

    /// Advances the drag. `time` is the time under the pointer and `row` the
    /// lane under it; snapping is applied to the GROUP's start so the whole
    /// selection clicks into place together.
    mutating func update(time: Ticks, row: Int, snapper: TimelineSnapper) {
        let raw = time - grabTime
        let resolved = snapper.resolve(spanStart + raw)
        delta = resolved.time - spanStart
        guide = resolved.guide
        // A clip can never start before zero (§6 clamps it); keeping the
        // preview honest about that stops the group sliding while the core
        // refuses to follow.
        if spanStart + delta < 0 { delta = -spanStart }
        self.row = row
        didMove = true
    }
}

// MARK: - Trim

/// Dragging a clip edge (spec §6 `trim_start` / `trim_end`), or with ⌥ a
/// rate stretch of the end.
///
/// **Pitfall:** `rate_stretch` only takes `to_end`, so ⌥ on the START edge
/// has nothing to express — it trims like a bare drag rather than pretending
/// to stretch and silently doing something else.
struct TrimSession {
    let clip: UInt32
    let edge: TimelineEdge
    let stretch: Bool
    /// The grabbed clip is a linked SOUND half, so its edge moves without
    /// its picture's — the J- or L-cut (spec §11 AU-93). A picture's edge
    /// carries to a sound whose edge coincides.
    let alone: Bool
    let originalStart: Ticks
    let originalEnd: Ticks
    /// One frame of the document's grid: the minimum a clip may keep.
    let frame: Ticks

    var time: Ticks
    var guide: Ticks?
    var didMove = false

    /// True when ⌥ actually changes the op.
    var isRateStretch: Bool { stretch && edge == .end }

    var op: ReelOp {
        switch edge {
        case .start:
            return .trimStart(clip: clip, to: min(time, originalEnd - frame), alone: alone)
        case .end:
            let to = max(time, originalStart + frame)
            return isRateStretch
                ? .rateStretch(clip: clip, toEnd: to)
                : .trimEnd(clip: clip, to: to, alone: alone)
        }
    }

    mutating func update(time: Ticks, snapper: TimelineSnapper) {
        let resolved = snapper.resolve(time)
        // Clamped here as well as in the core: the preview must not show an
        // inverted bar for the ticks the core is busy refusing.
        switch edge {
        case .start:
            self.time = max(0, min(resolved.time, originalEnd - frame))
        case .end:
            self.time = max(resolved.time, originalStart + frame)
        }
        guide = resolved.guide
        didMove = true
    }
}

// MARK: - The edge moves

/// ⌥⇧-dragging a clip's BODY: the source slides under a fixed clip
/// (spec §6 `slip`).
///
/// The op's `delta` is the TOTAL travel since mouse-down, not this tick's
/// increment, because `updateLiveEdit` re-applies against the handle the
/// gesture started from. It is also deliberately unsnapped: the thing being
/// moved is inside the media, where the timeline's candidates — other
/// clips' edges, the markers, the playhead — mean nothing. The core rounds
/// it to the frame grid, so the film still steps a frame at a time.
struct SlipSession {
    let clip: UInt32
    /// Time under the pointer at mouse-down, so the film keeps pace with
    /// the cursor.
    let grabTime: Ticks

    var delta: Ticks = 0
    var didMove = false

    var op: ReelOp { .slip(clip: clip, delta: delta) }

    mutating func update(time: Ticks) {
        delta = time - grabTime
        didMove = true
    }
}

/// ⌥⇧-dragging a clip's EDGE: the hard cut moves and nothing else does
/// (spec §6 `roll`).
///
/// Either edge rolls, but they roll DIFFERENT cuts, and the op only ever
/// names the clip on the cut's right: grabbing the start edge rolls this
/// clip against its predecessor, and grabbing the end edge rolls the
/// SUCCESSOR against this one. `clip` is resolved at mouse-down, so the
/// session itself has one job.
///

import AppKit

/// The seven commands a media row calls back into, and the one question it
/// asks: `drop`, `select`, `place`, `revealInTimeline`, `reveal` (in Finder),
/// `relink` and `remove`, plus `canRevealInTimeline`.
///
/// **Why they are a file of their own.** Every one of them applies an edit
/// through `binding`, or writes the document's view state, or puts a panel or
/// an alert up — which is the pane's business and never a row's
/// (`MediaRowView.swift` argues that half) — and none of them touches the
/// list's views except `select`, which redraws them. So they are a seam, not
/// an amputation: what is left in `MediaPane.swift` is the LIST — its one
/// section, its three chrome bands, the find band's arrangement and the Finder
/// drop onto the panel.
///
/// The cut is road map 2's phase 8c paying the ~600-line rule a second time
/// for this pane. The first payment (commit b189ac3) moved the row and its
/// drag out at 822 lines, precisely so this phase's four additions would have
/// room; the additions cost more than the room left, as phase 6 warned they
/// would ("budget the cut against the pessimistic number"). It costs ONE
/// widening — `MediaPane.rows`, which `select` redraws — which is the toll
/// `ExporterLoudness.swift` records for splitting a type across files, and it
/// is the whole of it, because everything else here was already internal for
/// the row to call.
extension MediaPane {
    /// Where a dragged row landed. Returns false when the drop is refused, so
    /// the drag springs back rather than silently doing nothing.
    func drop(_ media: UInt32, on destination: NSView, target: MediaDropTarget) -> Bool {
        // A drag started in ANOTHER document's panel must not edit this one:
        // the session carries the source row, and the two windows differ.
        guard destination.window === window, window != nil else { return false }
        guard binding.snapshot.media(media) != nil else { return false }
        let fps = binding.canvas.fps
        switch target {
        case .track(let track, let at, let mode):
            let when = ReelTime.snapToFrame(max(at, 0), fps: fps)
            switch mode {
            case .add:
                binding.apply("Add Clip", [.addClip(track: track, media: media, at: when)])
            case .insert:
                binding.apply("Insert", [.insertClip(track: track, media: media, at: when)])
            case .overwrite:
                binding.apply(
                    "Overwrite", [.overwriteClip(track: track, media: media, at: when)])
            }
        case .canvas:
            let at = ReelTime.snapToFrame(max(binding.playhead, 0), fps: fps)
            let index = binding.snapshot.tracks.count
            // `add_track` returns a project, not an id (§11's one entry
            // point), so the id is learned from a PURE trial application
            // before the real edit runs.
            let existing = Set(binding.snapshot.tracks.map { $0.id })
            let probed = inspector?.onProbe?([.addTrack(index: index)])
            guard let track = probed?.tracks.first(where: { !existing.contains($0.id) })?.id else {
                guard let top = binding.snapshot.tracks.last?.id else { return false }
                binding.apply("Add Clip", [.addClip(track: top, media: media, at: at)])
                return true
            }
            binding.apply(
                "Add Clip",
                [.addTrack(index: index), .addClip(track: track, media: media, at: at)])
        }
        return true
    }

    /// A row was clicked: it becomes the document's selected media, which is
    /// what Edit ▸ Insert / Overwrite at Playhead act on. View state, so it
    /// neither dirties the document nor registers an undo step.
    func select(_ media: UInt32) {
        guard let document = binding.document, document.selectedMedia != media else { return }
        document.selectedMedia = media
        // The rows draw the selection, and the Edit menu asks for it when it
        // validates; the Camera Log section (spec §11 GR-16) reads it too, so
        // the pane's controls refresh against the new row.
        rows.forEach { $0.view.needsDisplay = true }
        refresh()
    }

    /// A filter that hides the selected row clears the selection, so Insert /
    /// Overwrite at Playhead cannot place a row nobody can see (#68). No work
    /// when nothing selected is hidden: `arrange()` calls it on every refresh.
    func dropHiddenSelection() {
        guard let document = binding.document, let media = document.selectedMedia,
              let row = rows.first(where: { $0.media == media }), row.view.isHidden
        else { return }
        document.selectedMedia = nil
        row.view.needsDisplay = true
    }

    /// The row menu's Insert / Overwrite at Playhead. The same two ops the
        menu.autoenablesItems = false
        // Two groups: what to do with the file on the timeline, then what to
        // do with the file. The loop shape cannot express a separator, so the
        // groups are two loops with one between them.
        //
        // Reveal in Timeline is DISABLED where the file's only users are
        // inside a nest: a nested clip has no id the TIMELINE's selection can
        // hold (`MediaUsage.swift`), so the item would select nothing and
        // scroll nowhere. That case is exactly the one the pane's old
        // top-level-only usage test could not see. Since road map 2's phase 9
        // there IS a way to reach such a clip — open the nest (⌘↓) and it is
        // at the top level of the view — but that is a different command from
        // this one, which reveals on the timeline.
        for (title, selector) in [
            ("Insert at Playhead", #selector(insertMedia(_:))),
            ("Overwrite at Playhead", #selector(overwriteMedia(_:))),
            ("Reveal in Timeline", #selector(revealInTimeline(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            if selector == #selector(revealInTimeline(_:)) {
                item.isEnabled = pane?.canRevealInTimeline(media) ?? false
            } else if entry?.kind == .lut {
                item.isEnabled = false  // a LUT is not placed (GR-8)
            }
            menu.addItem(item)
        }
        menu.addItem(.separator())
        for (title, selector) in [
            ("Reveal in Finder", #selector(revealMedia(_:))),
            ("Relink…", #selector(relinkMedia(_:))),
}

// MARK: - Dragging a row out of the panel

extension NSPasteboard.PasteboardType {
    /// The private type a media row drags with. Deliberately NOT `.fileURL`:
    /// the editor's root view accepts file URLs and would open the file as a
    /// new document, which is not what dragging a row inside a project means.
    static let frameJobMedia = NSPasteboard.PasteboardType("com.kgalligan.framejob.media")
}

/// What a drop onto a lane does about the room the clip needs (spec §6).
///
/// The modifiers are the timeline's own, read at the moment of the drop:
/// none places the clip and lets the overlap rule refuse it, ⌥ makes room
/// for it and ⇧⌥ takes the room it needs. ⌥ alone is free here — the
/// duplicate-drag it means elsewhere is a gesture on a CLIP, and this drag
/// starts in the media list.
enum MediaDropMode: Equatable {
    case add
    case insert
    case overwrite

    /// The mode the modifiers currently held describe.
    static func current(_ flags: NSEvent.ModifierFlags) -> MediaDropMode {
        guard flags.contains(.option) else { return .add }
        return flags.contains(.shift) ? .overwrite : .insert
    }
}

/// Where a dragged media row landed.
enum MediaDropTarget: Equatable {
    /// A timeline track, at the time under the cursor, and what to do about
    /// what is already there.
    case track(UInt32, Ticks, MediaDropMode)
    /// The preview canvas: a new top track at the playhead (§4.3).
    case canvas
}

/// The media drag in flight. AppKit runs one drag at a time, so one slot is
/// enough — and it is what lets the destination views stay ignorant of the
/// document: they report WHERE the row landed and the pane that started the
/// drag performs the edit.
final class MediaDragSession {
    static var current: MediaDragSession?

    let media: UInt32
    /// The row being dragged; the pane checks its window against the
    /// destination's, so a drag between two open projects cannot edit the
    /// wrong one.
    weak var source: NSView?
    let drop: (NSView, MediaDropTarget) -> Bool

    init(media: UInt32, source: NSView, drop: @escaping (NSView, MediaDropTarget) -> Bool) {
        self.media = media
        self.source = source
        self.drop = drop
    }
}

// MARK: - Drop targets

/// The timeline as a drop target for a media row (§4.3: "drops at the
/// cursor"). Registered by `EditorViewController+Inspector.installInspector`;
/// the arithmetic is `TimelineLayout`'s, as it is for every other point in
/// that view.
extension TimelineView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        let point = content.convert(sender.draggingLocation, from: nil)
        guard let row = layout.row(atY: point.y), let track = track(atRow: row)
        else { return false }
        // `NSDraggingInfo` carries no modifiers, so the flags are read live —
        // which is right anyway: what matters is what is held at the DROP.
        let mode = MediaDropMode.current(
            NSEvent.modifierFlags.intersection(.deviceIndependentFlagsMask))
        return session.drop(
            self, .track(track.id, max(layout.time(atX: point.x), 0), mode))
    }
}

/// The preview canvas as a drop target: a media row dropped here appends on a
/// new top track at the playhead (§4.3).
extension PreviewCanvasView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        return session.drop(self, .canvas)
    }
}
    /// past either end it falls back to a constant pitch so "two rows below
    /// the bottom" still means something.
    func unclampedRow(atY y: CGFloat) -> Int {
        let pitch = Self.fallbackHeight(sizeIndex: heightIndex) + Self.laneSpacing
        guard y >= lanesTop else { return Int(((y - lanesTop) / pitch).rounded(.down)) }
        var top = lanesTop
        for row in 0..<max(trackCount, 0) {
            let bottom = top + rowPitch(row)
            if y < bottom { return row }
            top = bottom
        }
