            dragBase = nil
            dragHeights = [:]
            dragRowHeights = []
        } else if let session = trim {
            trim = nil
            onLiveEnd?(session.isRateStretch ? "Rate Stretch" : "Trim Clip")
        } else if slip != nil {
            slip = nil
            onLiveEnd?("Slip")
        } else if roll != nil {
            roll = nil
            onLiveEnd?("Roll")
        } else if markerDrag != nil {
            markerDrag = nil
            onLiveEnd?("Move Marker")
        } else if fadeDrag != nil {
            fadeDrag = nil
            onLiveEnd?("Set Fade")
        } else if volumeDrag != nil {
            endVolumeLine()
        } else if marquee != nil {
