    // MARK: - Gestures

    /// Everything a session needs to snap, built once per gesture so the
    /// candidate list is not re-fetched from the core on every mouse-moved.
    func makeSnapper(excluding clips: [UInt32], suppressed: Bool) -> TimelineSnapper {
        let core = onSnapCandidates?(clips) ?? []
        return TimelineSnapper(
            fps: snapshot.canvas.fps,
            candidates: TimelineSnapper.candidates(
                core: core, playhead: playhead, range: inOutRange),
            threshold: layout.snapThreshold,
            enabled: snappingEnabled && !suppressed)
    }

    /// Mouse-down. Picks the session that owns the hit and starts it; a click
    /// that only changes the selection starts none.
    func beginGesture(
        hit: TimelineHit, at point: CGPoint, flags: NSEvent.ModifierFlags, clicks: Int
    ) {
        endRename()
        let suppressed = flags.contains(.command)
        switch hit.resolvingVolumeLine(flags: flags, clicks: clicks) {
        case .none, .corner:
            break

        case .breadcrumb(let level):
            // The FIRST press only. AppKit delivers a double-click as two
            // mouse-downs (clickCount 1, then 2), and this cell is a BUTTON
            // that has already acted on the first: the trail is one component
            // shorter by the time the second arrives, `cornerHit` reads the
            // NEW trail, and the pair came out two levels for one gesture
            // (`TimelineView+NestScope.swift`).
            if clicks < 2 { onBreadcrumb?(level) }

        case .ruler(let time):
            var session = PlayheadSession(time: time, wasPlaying: false)
            dragSnapper = makeSnapper(excluding: [], suppressed: suppressed)
            session.update(time: time, snapper: dragSnapper)
            scrub = session
            onScrub?(session.time)

        case .marker(let id):
            guard let marker = snapshot.marker(id) else { break }
            if clicks == 2 {
                renameMarker(marker)
                break
            }
            dragSnapper = makeSnapper(excluding: [], suppressed: suppressed)
            markerDrag = MarkerDragSession(marker: id, original: marker.time, time: marker.time)
            onLiveBegin?()

        case .header(let row):
            guard let track = track(atRow: row) else { break }
            if clicks == 2 {
                renameTrack(track, row: row)
                break
            }
            if flags.contains(.option) {
                selectClipsOnTrack(track.id)
                break
            }
            trackDrag = TrackDragSession(
                track: track.id, originalRow: row, trackCount: snapshot.tracks.count, row: row)

        case .headerButton(let row, let button):
            toggleHeader(button, row: row)

        case .clip(let id):
            // ⌥⇧ before the selection, deliberately: `selectClip` reads ⇧ as
            // "toggle membership" and would drop the clip out of the
            // selection on the way into its own slip.
            if flags.contains(.option), flags.contains(.shift) {
                beginSlip(id, at: point, flags: flags)
                break
            }
            // A double-click on a NEST clip goes INSIDE it (road map 2's
            // phase 9) — above the rename branch, so opening wins where both
            // could apply, which is the stronger meaning of the gesture in
            // every editor that has both. The consequence is a REMOVAL and is
            // said out loud in `EditorViewController+NestScope.swift`: a nest
            // clip loses rename-by-double-click, keeping ⇧⌘R, Clip ▸ Rename…
            // and the Clip tab's header field. Like the ⌥⇧ slip above it
            // short-circuits before `selectClip`.
            if clicks == 2, snapshot.clip(id)?.source.nestID != nil {
                onOpenNest?(id)
                break
            }
            // A double-click renames (TimelineView+Rename.swift) — also
            // before the selection, for the same reason.
            if clicks == 2 {
                beginClipRename(id)
                break
            }
            selectClip(id, flags: flags)
            beginClipDrag(anchor: id, at: point, flags: flags)

        case .clipEdge(let id, let edge):
            if flags.contains(.option), flags.contains(.shift) {
                beginRoll(id, edge: edge, flags: flags)
                break
            }
            selectClip(id, flags: flags)
            beginTrim(id, edge: edge, flags: flags)

        case .fade(let id, let edge):
            guard let clip = snapshot.clip(id) else { break }
            let props = clip.audioProps
            fadeDrag = FadeHandleSession(
                clip: id, edge: edge, clipStart: clip.start, clipEnd: clip.end,
                length: edge == .start ? props.fadeIn : props.fadeOut)
            onLiveBegin?()

        case .volumeLine(let id, let time):
            selectClip(id, flags: [])
            beginVolumeLine(id, at: point, time: time, flags: flags)

        case .action(let clip, let action):
            selectClip(clip, flags: [])
            onActionSelected?(clip, action)
            beginActionDrag(clip: clip, action: action, mode: .move, at: point)

        case .actionEdge(let clip, let action, let edge):
            selectClip(clip, flags: [])
            onActionSelected?(clip, action)
            beginActionDrag(clip: clip, action: action, mode: .resize(edge), at: point)

        case .lane(let row, let time):
            // A double-click in empty lane space closes the gap it landed
            // in. The single click AppKit delivered first started and ended
            // a marquee, which registers nothing.
            if clicks == 2 {
                ops.append(
                    .setActionEnd(clip: clip.id, action: inside.id, patch: end(animated), schema: schema))
            }
        }
        if !ids.isEmpty { ops.insert(base(ids, patch), at: 0) }
        return ops
    }

    // MARK: Commits

    func apply(_ name: String, _ ops: [ReelOp]) {
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        inspector?.onEdit?(name, ops)
    }

    func apply(_ name: String, video patch: VideoPatch) { apply(name, ops(video: patch)) }
    func apply(_ name: String, audio patch: AudioPatch) { apply(name, ops(audio: patch)) }
    func apply(_ name: String, text patch: TextPatch) { apply(name, ops(text: patch)) }
    func apply(_ name: String, shape patch: ShapePatch) { apply(name, ops(shape: patch)) }

    /// `apply` as one undo step with the step that ended at `step` — undone
    /// first when nothing has been applied since (#272, a wheel strip's
    /// off-knob double-click; `ProjectDocument.applyEdit(_:_:amending:)`).
    func amend(_ name: String, _ ops: [ReelOp], step: ReelProject) {
        guard !ops.isEmpty else {
            NSSound.beep()
            return
        }
        inspector?.onAmendEdit?(name, ops, step)
    }

